# Created by OpenAI
"""Shared MoE arithmetic, tile-layout, asynchronous-copy, and reduction primitives."""
from triton.experimental import gluon
from triton.experimental.gluon import language as gl

@gluon.jit
def _sigmoid(x):
    return 1.0 / (1.0 + gl.exp(-x))

@gluon.jit
def _weight_offset(n, k, K: gl.constexpr):
    return n // 16 * K * 16 + k // 16 * 256 + n % 16 * 16 + k % 16

@gluon.jit
def _pop_four(k0, k1, k2, k3, maximum):
    take = k0 == maximum
    return (gl.where(take, k1, k0), gl.where(take, k2, k1), gl.where(take, k3, k2), gl.where(take, 0, k3))

# Created by OpenAI
from triton.experimental import gluon
from triton.experimental.gluon import language as gl

@gluon.jit
def _float_order(score):
    bits = score.to(gl.uint32, bitcast=True)
    return gl.where(bits & 2147483648 != 0, ~bits, bits ^ 2147483648)

# Created by OpenAI
"""GLM-5.2 FP8 MoE, TP4 (512 intermediate rows per expert on this rank), for 1 token.

deepseek_v2_fp8_moe for GLM-5.2's fp8 experts on gfx950: the router's logits rounded to bf16,
their sigmoid scores plus the bf16 correction bias ranking the 256 routed experts in one group,
each token's top 8 (the lower index first among equals), their weights renormalized times 2.5,
and the shared expert in slot 256 at weight 1; the activations quantized to fp8 per 1 x 128
group, each expert's gate-up and down GEMMs on sglang's preshuffled fp8 weights and fp32
128 x 128 block scales, and their weighted sum written to out, this rank's share.

Four launches: the router GEMV (each logit rounded to bf16, scored and biased) beside the
input's fp8 quantization; route selection with the gate-up GEMM of the 9 routes; the
activation's fp8 quantization; a packed down projection over the token's routes into out.
"""

from typing import NamedTuple
from triton.experimental import gluon
from triton.experimental.gluon import language as gl
from triton.language.core import range as _loop_range
from ._decode import _float_order
from ._common import _pop_four as _pop_lane_queue, _sigmoid, _weight_offset as _offset
import torch

@gluon.jit
def _quantize_group(x):
    rank: gl.constexpr = len(x.type.shape)
    scale = gl.div_rn(gl.maximum(gl.max(gl.abs(x), rank - 1), 1e-10), 448.0)
    inverse = gl.div_rn(1.0, scale)
    return (x * (inverse[:, None] if rank == 2 else inverse), scale)

@gluon.jit
def _packed_bf16(x):
    shape: gl.constexpr = x.type.shape
    lo, hi = gl.split(gl.reshape(x.to(gl.uint16, bitcast=True), shape[:-1] + (shape[-1] // 2, 2)))
    return lo.to(gl.uint32) | hi.to(gl.uint32) << 16

@gluon.jit
def _packed_dot_bf16(x, w):
    return gl.inline_asm_elementwise('v_mov_b32 $0, 0\n v_dot2c_f32_bf16 $0, $1, $2', '=&v,v,v', [x, w], dtype=gl.float32, is_pure=True, pack=1)

@gluon.jit
def _quantize_hidden_rows(X, Q, S, row, group, LAYOUT: gl.constexpr):
    k = group * 128 + gl.arange(0, 128, layout=gl.SliceLayout(0, LAYOUT))
    x = gl.load(X + row[:, None] * 6144 + k[None, :]).to(gl.float32)
    quantized, scale = _quantize_group(x)
    gl.store(Q + row[:, None] * 6144 + k[None, :], quantized.to(Q.dtype.element_ty))
    gl.store(S + row * 48 + group, scale)

@gluon.jit
def _compact_scores(scores, ORDERS: gl.constexpr, PACKED: gl.constexpr=False):
    if PACKED:
        upper = scores >= (3221225472 if ORDERS else 2.0)
        if not ORDERS:
            upper |= scores != scores
        count = gl.sum((scores >= (3204448256 if ORDERS else 0.5)).to(gl.int32) + upper.to(gl.int32) * 512, 0)
        return (count >= 8) & (count < 512)
    return (gl.max(scores, 0) < (3221225472 if ORDERS else 2.0)) & (gl.sum((scores >= (3204448256 if ORDERS else 0.5)).to(gl.int32), 0) >= 8)

@gluon.jit
def _selection_keys(scores, experts, ORDERS: gl.constexpr, WIDE: gl.constexpr):
    if WIDE:
        order = scores if ORDERS else _float_order(scores)
        keys = order.to(gl.uint64) << 32 | (255 - experts).to(gl.uint64)
    elif ORDERS:
        keys = gl.where(scores >= 3204448256, scores - 3204448256 << 8 | (255 - experts).to(gl.uint32), 0)
    else:
        keys = gl.where(scores >= 0.5, scores.to(gl.uint32, bitcast=True) - 1056964608 << 8 | (255 - experts).to(gl.uint32), 0)
    return keys

@gluon.jit
def _publish_routes(Ids, Weights, row, ids, probabilities, FACTOR: gl.constexpr):
    slot = gl.arange(0, 8, layout=ids.type.layout)
    gl.store(Ids + row * 9 + slot, ids)
    gl.store(Weights + row * 9 + slot, probabilities / gl.sum(probabilities, 0) * FACTOR)
    gl.store(Ids + row * 9 + 8, 256)
    gl.store(Weights + row * 9 + 8, 1.0)

@gluon.jit
def _store_router_row(Bias, Scores, Probs, row, expert, value, ORDERS: gl.constexpr):
    if Probs is None:
        gl.store(Scores + row * 256 + expert, value)
    else:
        probability = _sigmoid(value.to(gl.bfloat16).to(gl.float32))
        score = probability + gl.load(Bias + expert).to(gl.float32)
        gl.store(Scores + row * 256 + expert, _float_order(score) if ORDERS else score)
        gl.store(Probs + row * 256 + expert, probability)

@gluon.jit
def _prepare(X, W, Q, S, Bias, Scores, Probs, ROWS: gl.constexpr, ORDERS: gl.constexpr):
    row = gl.program_id(0) * ROWS
    job = gl.program_id(1)
    lay: gl.constexpr = gl.BlockedLayout([2], [64], [4], [0])
    if ROWS == 4 or job < 256:
        k = gl.arange(0, 8192, layout=lay)
        if ROWS == 4:
            w = _packed_bf16(gl.load(W + job * 6144 + k, k < 6144, 0))
        x = _packed_bf16(gl.load(X + row * 6144 + k, k < 6144, 0))
        if ROWS >= 2:
            y = _packed_bf16(gl.load(X + (row + 1) * 6144 + k, k < 6144, 0))
        if ROWS == 4:
            x2 = _packed_bf16(gl.load(X + (row + 2) * 6144 + k, k < 6144, 0))
            x3 = _packed_bf16(gl.load(X + (row + 3) * 6144 + k, k < 6144, 0))
        else:
            w = _packed_bf16(gl.load(W + job * 6144 + k, k < 6144, 0))
        prod = _packed_dot_bf16(x, w)
        if ROWS >= 2:
            prod_y = _packed_dot_bf16(y, w)
            if ROWS == 4:
                p2, p3 = (_packed_dot_bf16(x2, w), _packed_dot_bf16(x3, w))
                products = gl.reshape(gl.join(gl.join(prod, p2), gl.join(prod_y, p3)), (4096, 4))
            else:
                products = gl.join(prod, prod_y)
            value = gl.sum(products, 0)
            output_row = row + gl.arange(0, ROWS, layout=value.type.layout)
        else:
            pk = gl.arange(0, 4096, layout=prod.type.layout)
            value = gl.sum(gl.where(pk < 3072, prod, 0.0), 0)
            output_row = row
        _store_router_row(Bias, Scores, Probs, output_row, job, value, ORDERS)
    else:
        group = job - 256
        qk = group * 128 + gl.arange(0, 128, layout=lay)
        quantized, scale = _quantize_group(gl.load(X + row * 6144 + qk).to(gl.float32))
        gl.store(Q + row * 6144 + qk, quantized.to(Q.dtype.element_ty))
        gl.store(S + row * 48 + group, scale)
        if ROWS == 2:
            quantized_y, scale_y = _quantize_group(gl.load(X + (row + 1) * 6144 + qk).to(gl.float32))
            gl.store(Q + (row + 1) * 6144 + qk, quantized_y.to(Q.dtype.element_ty))
            gl.store(S + (row + 1) * 48 + group, scale_y)
    if ROWS == 4:
        if job < 48:
            qlay: gl.constexpr = gl.BlockedLayout([1, 2], [1, 64], [4, 1], [1, 0])
            qr = row + gl.arange(0, 4, layout=gl.SliceLayout(1, qlay))
            _quantize_hidden_rows(X, Q, S, qr, job, qlay)

@gluon.jit
def _prepare_matrix(X, W, Q, S, Partials, M: gl.constexpr, SPLITS: gl.constexpr, BN: gl.constexpr, KW: gl.constexpr):
    tile, split = (gl.program_id(0), gl.program_id(1))
    ml: gl.constexpr = gl.amd.AMDMFMALayout(version=4, instr_shape=[16, 16, 32], transposed=True, warps_per_cta=[1, 1])
    al: gl.constexpr = gl.DotOperandLayout(0, ml, KW)
    bl: gl.constexpr = gl.DotOperandLayout(1, ml, KW)
    row = gl.arange(0, 16, layout=gl.SliceLayout(1, al))
    ka = gl.arange(0, 128, layout=gl.SliceLayout(0, al))
    kb = gl.arange(0, 128, layout=gl.SliceLayout(1, bl))
    col = tile * BN + gl.arange(0, BN, layout=gl.SliceLayout(0, bl))
    acc = gl.full((16, BN), 0, gl.float64, ml)
    for group in range(48 // SPLITS):
        k = (split * (48 // SPLITS) + group) * 128
        a = gl.load(X + row[:, None] * 6144 + k + ka[None, :], row[:, None] < M, 0)
        b = gl.load(W + col[None, :] * 6144 + k + kb[:, None])
        part = gl.amd.cdna4.mfma(a, b, gl.full((16, BN), 0, gl.float32, ml))
        acc += part.to(gl.float64)
    mr = gl.arange(0, 16, layout=gl.SliceLayout(1, ml))
    nc = tile * BN + gl.arange(0, BN, layout=gl.SliceLayout(0, ml))
    gl.store(Partials + (mr[:, None] * SPLITS + split) * 256 + nc[None, :], acc, mr[:, None] < M)
    gl.static_assert(M == 16 and SPLITS == 12 and (BN == 16))
    qlay: gl.constexpr = gl.BlockedLayout([1, 2], [1, 64], [1, 1], [1, 0])
    qg = split * 4 + gl.arange(0, 4, layout=gl.SliceLayout(1, qlay))
    qk = qg[:, None] * 128 + gl.arange(0, 128, layout=gl.SliceLayout(0, qlay))[None, :]
    qx = gl.load(X + tile * 6144 + qk).to(gl.float32)
    quantized, scale = _quantize_group(qx)
    gl.store(Q + tile * 6144 + qk, quantized.to(Q.dtype.element_ty))
    gl.store(S + tile * 48 + qg, scale)

@gluon.jit
def _lane_queue(keys, NATIVE: gl.constexpr):
    a, b = gl.split(gl.reshape(keys, (64, 2, 2)))
    k0, k2 = gl.split(a)
    k1, k3 = gl.split(b)
    if NATIVE and keys.dtype == gl.uint32:
        return gl.inline_asm_elementwise('v_max_u32 $0, $6, $7\nv_min_u32 $3, $6, $7\nv_med3_u32 $1, $4, $5, $0\nv_med3_u32 $2, $4, $5, $3\nv_max_u32 $1, $1, $3\nv_min_u32 $2, $2, $0\nv_max3_u32 $0, $4, $5, $0\nv_min3_u32 $3, $4, $5, $3', '=&v,=&v,=&v,=&v,v,v,v,v', [k0, k1, k2, k3], dtype=(gl.uint32, gl.uint32, gl.uint32, gl.uint32), is_pure=True, pack=1)
    hi01, lo01 = (gl.maximum(k0, k1), gl.minimum(k0, k1))
    hi23, lo23 = (gl.maximum(k2, k3), gl.minimum(k2, k3))
    h0, t0 = (gl.maximum(hi01, hi23), gl.minimum(hi01, hi23))
    t1, h3 = (gl.maximum(lo01, lo23), gl.minimum(lo01, lo23))
    return (h0, gl.maximum(t0, t1), gl.minimum(t0, t1), h3)

@gluon.jit
def _select_keys(keys, rank, NATIVE: gl.constexpr):
    h0, h1, h2, h3 = _lane_queue(keys, NATIVE)
    ID_BITS: gl.constexpr = 8 if keys.dtype == gl.uint32 else 32
    if rank is None:
        slots = gl.arange(0, 8, layout=keys.type.layout)
        ids = gl.full((8,), 0, gl.int32, keys.type.layout)
        for index in gl.static_range(8):
            best = gl.max(h0, 0)
            winner = 255 - (best & (1 << ID_BITS) - 1).to(gl.int32)
            ids = gl.where(slots == index, winner, ids)
            h0, h1, h2, h3 = _pop_lane_queue(h0, h1, h2, h3, best)
        return ids
    else:
        best = gl.full((), 0, keys.dtype, gl.BlockedLayout([1], [64], [1], [0]))
        for index in range(rank + 1):
            best = gl.max(h0, 0)
            h0, h1, h2, h3 = _pop_lane_queue(h0, h1, h2, h3, best)
        return 255 - (best & (1 << ID_BITS) - 1).to(gl.int32)

@gluon.jit
def _select_scores(scores, experts, rank, ORDERS: gl.constexpr, PACKED: gl.constexpr=False):
    if _compact_scores(scores, ORDERS, PACKED):
        return _select_keys(_selection_keys(scores, experts, ORDERS, False), rank, not ORDERS)
    else:
        return _select_keys(_selection_keys(scores, experts, ORDERS, True), rank, not ORDERS)

@gluon.jit
def _select(L, Bias, Ids, Weights, FACTOR: gl.constexpr, SPLITS: gl.constexpr=0):
    row = gl.program_id(0)
    lay: gl.constexpr = gl.BlockedLayout([4], [64], [1], [0])
    e = gl.arange(0, 256, layout=lay)
    if SPLITS:
        merged = gl.full((256,), 0, gl.float64, lay)
        for split in gl.static_range(SPLITS):
            merged += gl.load(L + (row * SPLITS + split) * 256 + e)
        logit = merged.to(gl.bfloat16).to(gl.float32)
    else:
        logit = gl.load(L + row * 256 + e).to(gl.float32)
    p = _sigmoid(logit)
    scores = p + gl.load(Bias + e).to(gl.float32)
    ids = _select_scores(scores, e, None, False)
    _publish_routes(Ids, Weights, row, ids, gl.gather(p, ids, 0), FACTOR)

@gluon.jit
def _route_from_scores(Scores, Probs, Ids, Weights, job, tile, split, FACTOR: gl.constexpr, ORDERS: gl.constexpr, PACKED: gl.constexpr=False):
    row, slot = (job // 9, job % 9)
    expert = 256
    if slot < 8:
        expert_lay: gl.constexpr = gl.BlockedLayout([4], [64], [1], [0])
        experts = gl.arange(0, 256, layout=expert_lay)
        scores = gl.load(Scores + row * 256 + experts)
        expert = _select_scores(scores, experts, slot, ORDERS, PACKED)
    if (slot == 0) & (tile == 0) & (split == 0):
        lay: gl.constexpr = gl.BlockedLayout([1], [64], [1], [0])
        e = gl.arange(0, 256, layout=lay)
        score = gl.load(Scores + row * 256 + e)
        prob = gl.load(Probs + row * 256 + e)
        slots = gl.arange(0, 8, layout=lay)
        values = _selection_keys(score, e, True, True) if ORDERS else score
        ids = gl.full((8,), 0, gl.int32, lay)
        for rank in gl.static_range(8):
            maximum = gl.max(values, 0)
            if ORDERS:
                winner = 255 - (maximum & 4294967295).to(gl.int32)
            else:
                winner = gl.min(gl.where(values == maximum, e, 256), 0)
            values = gl.where(e == winner, 0 if ORDERS else -float('inf'), values)
            ids = gl.where(slots == rank, winner, ids)
        _publish_routes(Ids, Weights, row, ids, gl.gather(prob, ids, 0), FACTOR)
    return expert

@gluon.jit
def _live_routes(Ids, Scores, expert, M: gl.constexpr, BM: gl.constexpr):
    if Scores is not None:
        lay: gl.constexpr = gl.BlockedLayout([1, 4], [1, 64], [1, 1], [1, 0])
        small_row = gl.arange(0, M, layout=gl.SliceLayout(1, lay))
        row_lay: gl.constexpr = gl.BlockedLayout([1], [64], [1], [0])
    else:
        lay: gl.constexpr = gl.BlockedLayout([1, 1], [M, 64 // M], [1, 1], [1, 0])
        row_lay: gl.constexpr = gl.SliceLayout(1, lay)
    row = gl.arange(0, BM, layout=row_lay)
    if expert == 256:
        route, active, first = (row * 9 + 8, row < M, 8)
    elif Scores is not None:
        e = gl.arange(0, 256, layout=gl.SliceLayout(0, lay))
        codes = gl.load(Scores + small_row[:, None] * 256 + e[None, :])
        target = gl.load(Scores + small_row * 256 + expert)
        preceding = (codes > target[:, None]) | (codes == target[:, None]) & (e[None, :] < expert)
        small_slot = gl.sum(preceding.to(gl.int32), 1)
        first = gl.min(gl.where(small_slot < 8, small_row * 9 + small_slot, M * 9), 0)
        slots = gl.convert_layout(small_slot, row_lay)
        slot = gl.gather(slots, gl.minimum(row, M - 1), 0)
        active = (row < M) & (slot < 8)
        route = row * 9 + slot
    else:
        slot = gl.arange(0, 8, layout=gl.SliceLayout(0, lay))
        ids = gl.load(Ids + row[:, None] * 9 + slot[None, :], row[:, None] < M, -1)
        route = gl.min(gl.where(ids == expert, row[:, None] * 9 + slot[None, :], M * 9), 1)
        active = route < M * 9
        first = gl.min(route, 0)
    return (gl.where(active, route, 0), gl.where(active, row, 0), active, first)

@gluon.jit
def _prefetch_projection_group(X, XS, W, WS, source, sources, expert, n, ka, kb, group, tile, N: gl.constexpr, K: gl.constexpr, P: gl.constexpr, HOIST: gl.constexpr, CACHE_HINT: gl.constexpr):
    if P.buffer_input:
        a = gl.amd.cdna4.buffer_load(X, source[:, None] * K + group * 128 + ka[None, :])
    else:
        a = gl.load(X + source[:, None] * K + group * 128 + ka[None, :])
    if HOIST:
        base = gl.multiple_of(expert.to(gl.int64) * N * K + tile.to(gl.int64) * P.cols * K, 16)
        local_n = (n[None, :] - tile * P.cols).to(gl.uint32)
        local_k = (group * 128 + kb[:, None]).to(gl.uint32)
        offsets = gl.max_contiguous(_offset(local_n, local_k, K), (16, 1))
        b = gl.amd.cdna4.buffer_load(W + base, offsets, cache=CACHE_HINT)
    else:
        b = gl.amd.cdna4.buffer_load(W + expert.to(gl.int64) * N * K, _offset(n[None, :], group * 128 + kb[:, None], K), cache=CACHE_HINT)
    sa = gl.load(XS + sources * (K // 128) + group)
    sb = gl.load(WS + (expert * (N // 128) + tile * P.cols // 128) * (K // 128) + group)
    return (a, b, sa, sb)

@gluon.jit
def _accumulate_projection_group(a, b, sa, sb, acc, NATIVE: gl.constexpr):
    zero = gl.full(acc.shape, 0, gl.float32, acc.type.layout)
    if NATIVE:
        partial = gl.amd.cdna4.mfma_scaled(a, None, 'e4m3', b, None, 'e4m3', zero)
    else:
        partial = gl.amd.cdna4.mfma(a, b, zero)
    return acc + partial * sa[:, None] * sb

@gluon.jit
def _projection_tile(X, XS, W, WS, Y, expert, job, tile, split, live_route, live_source, active, N: gl.constexpr, K: gl.constexpr, SOURCE_STRIDE: gl.constexpr, P: gl.constexpr, GROUPED: gl.constexpr, HOIST: gl.constexpr, CACHE_HINT: gl.constexpr=None):
    BM: gl.constexpr = P.rows
    BN: gl.constexpr = P.cols
    SPLIT: gl.constexpr = P.splits
    cache_hint: gl.constexpr = P.cache if CACHE_HINT is None else CACHE_HINT
    ml: gl.constexpr = gl.amd.AMDMFMALayout(version=4, instr_shape=[16, 16, 128 if P.native else 32], transposed=True, warps_per_cta=[1, 1])
    al: gl.constexpr = gl.DotOperandLayout(0, ml, P.k_width)
    bl: gl.constexpr = gl.DotOperandLayout(1, ml, P.k_width)
    route = job + gl.full((BM,), 0, gl.int32, gl.SliceLayout(1, al))
    if GROUPED:
        route = gl.convert_layout(live_route, gl.SliceLayout(1, al))
        source = route if SOURCE_STRIDE == 1 else gl.convert_layout(live_source, gl.SliceLayout(1, al))
    else:
        source = gl.full((BM,), 0, gl.int32, gl.SliceLayout(1, al)) if SOURCE_STRIDE == 0 else route // SOURCE_STRIDE
    ka = gl.arange(0, 128, layout=gl.SliceLayout(0, al))
    kb = gl.arange(0, 128, layout=gl.SliceLayout(1, bl))
    nn = tile * BN + gl.arange(0, BN, layout=gl.SliceLayout(0, bl))
    am = gl.arange(0, BM, layout=gl.SliceLayout(1, ml))
    an = tile * BN + gl.arange(0, BN, layout=gl.SliceLayout(0, ml))
    sources = gl.convert_layout(source, gl.SliceLayout(1, ml))
    routes = gl.convert_layout(route, gl.SliceLayout(1, ml))
    output_row = gl.convert_layout(active, gl.SliceLayout(1, ml)) if GROUPED else am == 0
    acc = gl.full((BM, BN), 0, gl.float32, ml)
    gl.static_assert(128 % BN == 0)
    gl.static_assert(K // 128 % SPLIT == 0 and N % BN == 0)
    gl.static_assert(K // 128 // SPLIT % P.prefetch == 0)
    for block in _loop_range(0, K // 128 // SPLIT // P.prefetch, loop_unroll_factor=4 if P.prefetch == 1 else 1):
        g0 = split * (K // 128 // SPLIT) + block * P.prefetch
        prefetched = ()
        for stage in gl.static_range(P.prefetch):
            prefetched += (_prefetch_projection_group(X, XS, W, WS, source, sources, expert, nn, ka, kb, g0 + stage, tile, N, K, P, HOIST, cache_hint),)
        for stage in gl.static_range(P.prefetch):
            a, b, sa, sb = prefetched[stage]
            acc = _accumulate_projection_group(a, b, sa, sb, acc, P.native)
    offsets = (routes[:, None] * SPLIT + split) * N + an[None, :]
    if P.buffer_output:
        gl.amd.cdna4.buffer_store(acc.to(Y.dtype.element_ty), Y, offsets, output_row[:, None])
    else:
        gl.store(Y + offsets, acc, output_row[:, None])

@gluon.jit
def _project_up(X, XS, W, WS, Ids, Y, Scores, Probs, Weights, RouteMap, M: gl.constexpr, FACTOR: gl.constexpr, P: gl.constexpr, AXES: gl.constexpr, SINGLE: gl.constexpr=None):
    gl.static_assert(P.rows >= M)
    tile = gl.program_id(AXES[0])
    job = gl.program_id(AXES[1])
    split = gl.program_id(AXES[2])
    if M > 1:
        job = gl.where(job < M * 8, job // 8 * 9 + job % 8, 8)
    if M <= 4:
        expert = _route_from_scores(Scores, Probs, Ids, Weights, job, tile, split, FACTOR, M == 4, M == 1)
    else:
        expert = gl.load(Ids + job)
    if M >= 4:
        live_route, live_source, active, first = _live_routes(Ids, Scores, expert, M, P.rows)
        if M >= 8:
            if (tile == 0) & (split == 0):
                gl.store(RouteMap + job * (P.rows + 1) + P.rows, gl.where(job == first, expert + 1, 0))
                if job == first:
                    map_row = gl.arange(0, P.rows, layout=live_route.type.layout)
                    gl.store(RouteMap + job * (P.rows + 1) + map_row, gl.where(active, live_route, -1))
        if job != first:
            return
    else:
        live_route, live_source, active = (None, None, None)
    if M == 2 and job == 8:
        lay: gl.constexpr = gl.BlockedLayout([1], [64], [1], [0])
        row = gl.arange(0, P.rows, layout=lay)
        shared_active = row < M
        shared_route = gl.where(shared_active, row * 9 + 8, 0)
        shared_source = gl.where(shared_active, row, 0)
        _projection_tile(X, XS, W, WS, Y, expert, job, tile, split, shared_route, shared_source, shared_active, 1024, 6144, 9, P, True, M >= 8)
    elif SINGLE is not None:
        if gl.sum(active.to(gl.int32), 0) == 1:
            _projection_tile(X, XS, W, WS, Y, expert, job, tile, split, None, None, None, 1024, 6144, 9, SINGLE, False, True, '.cg')
        else:
            _projection_tile(X, XS, W, WS, Y, expert, job, tile, split, live_route, live_source, active, 1024, 6144, 9, P, True, True)
    else:
        _projection_tile(X, XS, W, WS, Y, expert, job, tile, split, live_route, live_source, active, 1024, 6144, 0 if M == 1 else 9, P, M >= 4, M >= 8)

@gluon.jit
def _project_down(X, XS, W, WS, Y, RouteMap, M: gl.constexpr, P: gl.constexpr):
    tile, job = (gl.program_id(0), gl.program_id(1))
    job = gl.where(job < M * 8, job // 8 * 9 + job % 8, 8)
    header = gl.load(RouteMap + job * (P.rows + 1) + P.rows)
    if header == 0:
        return
    lay: gl.constexpr = gl.BlockedLayout([1], [64], [1], [0])
    row = gl.arange(0, P.rows, layout=lay)
    stored_route = gl.load(RouteMap + job * (P.rows + 1) + row)
    active = stored_route >= 0
    live_route = gl.where(active, stored_route, 0)
    _projection_tile(X, XS, W, WS, Y, header - 1, job, tile, 0, live_route, None, active, 6144, 512, 1, P, True, False)

@gluon.jit
def _activate_quant(P, Q, S, SPLIT: gl.constexpr):
    route, group = (gl.program_id(0), gl.program_id(1))
    lay: gl.constexpr = gl.BlockedLayout([1], [64], [1], [0])
    k = group * 128 + gl.arange(0, 128, layout=lay)
    gate = gl.full((128,), 0, gl.float32, lay)
    up = gl.full((128,), 0, gl.float32, lay)
    for split in gl.static_range(SPLIT):
        base = P + (route * SPLIT + split) * 1024 + k
        gate += gl.load(base)
        up += gl.load(base + 512)
    gate = gate.to(gl.bfloat16).to(gl.float32)
    up = up.to(gl.bfloat16).to(gl.float32)
    x = (gate * _sigmoid(gate) * up).to(gl.bfloat16).to(gl.float32)
    quantized, scale = _quantize_group(x)
    gl.store(Q + route * 512 + k, quantized.to(Q.dtype.element_ty))
    gl.store(S + route * 4 + group, scale)

@gluon.jit
def _combine(Y, Weights, Out):
    row = gl.program_id(0)
    lay: gl.constexpr = gl.BlockedLayout([4], [64], [1], [0])
    k = gl.program_id(1) * 256 + gl.arange(0, 256, layout=lay)
    acc = gl.full((256,), 0, gl.float32, lay)
    for slot in gl.static_range(9):
        v = gl.load(Y + (row * 9 + slot) * 6144 + k).to(gl.float32)
        w = gl.load(Weights + row * 9 + slot)
        acc += v * w
    gl.store(Out + row * 6144 + k, acc)

@gluon.jit
def _down_packed(X, XS, W, WS, Ids, Weights, Out, P: gl.constexpr, SEPARATE_SHARED: gl.constexpr):
    BN: gl.constexpr = P.cols
    gl.static_assert(128 % BN == 0 and 4 % P.prefetch == 0)
    R: gl.constexpr = 8 if SEPARATE_SHARED else 16
    LIVE: gl.constexpr = 8 if SEPARATE_SHARED else 9
    NW: gl.constexpr = gl.num_warps()
    tile, row = (gl.program_id(0), gl.program_id(1))
    ml: gl.constexpr = gl.amd.AMDMFMALayout(version=4, instr_shape=[16, 16, 128], transposed=False, warps_per_cta=[1, NW])
    al: gl.constexpr = gl.DotOperandLayout(0, ml, P.k_width)
    bl: gl.constexpr = gl.DotOperandLayout(1, ml, P.k_width)
    ar = gl.arange(0, R, layout=gl.SliceLayout(1, al))
    ak = gl.arange(0, 128, layout=gl.SliceLayout(0, al))
    bk = gl.arange(0, 128, layout=gl.SliceLayout(1, bl))
    bn = gl.arange(0, BN * R, layout=gl.SliceLayout(0, bl))
    mask_n = None if SEPARATE_SHARED else bn // BN < LIVE
    zero: gl.constexpr = None if SEPARATE_SHARED else 0
    fp8_zero: gl.constexpr = None if SEPARATE_SHARED else 0.0
    expert = gl.load(Ids + row * 9 + bn // BN, mask_n, zero)
    cn = gl.arange(0, BN * R, layout=gl.SliceLayout(0, ml))
    mask_c = None if SEPARATE_SHARED else cn // BN < LIVE
    mask_a = None if SEPARATE_SHARED else ar[:, None] < LIVE
    mask_b = None if SEPARATE_SHARED else mask_n[None, :]
    scale_expert = gl.load(Ids + row * 9 + cn // BN, mask_c, zero)
    acc = gl.full((BN * R,), 0, gl.float32, gl.SliceLayout(0, ml))
    if SEPARATE_SHARED:
        sn = tile * BN + gl.arange(0, BN, layout=gl.SliceLayout(0, bl))
        shared_row = gl.arange(0, 1, layout=gl.SliceLayout(1, al))
        shared_acc = gl.full((1, BN), 0, gl.float32, ml)
    for block in range(4 // P.prefetch):
        operands = ()
        for stage in gl.static_range(P.prefetch):
            group = block * P.prefetch + stage
            a = gl.load(X + (row * 9 + ar[:, None]) * 512 + group * 128 + ak[None, :], mask_a, fp8_zero)
            b = gl.amd.cdna4.buffer_load(W, expert[None, :] * 6144 * 512 + _offset(tile * BN + bn[None, :] % BN, group * 128 + bk[:, None], 512), mask_b, fp8_zero)
            sa = gl.load(XS + (row * 9 + cn // BN) * 4 + group, mask_c, zero)
            sb = gl.load(WS + (scale_expert * 48 + tile * BN // 128) * 4 + group, mask_c, zero)
            if SEPARATE_SHARED:
                shared_a = gl.load(X + (row * 9 + 8 + shared_row[:, None]) * 512 + group * 128 + ak[None, :])
                shared_b = gl.amd.cdna4.buffer_load(W + 256 * 6144 * 512, _offset(sn[None, :], group * 128 + bk[:, None], 512))
                shared_sa = gl.load(XS + (row * 9 + 8) * 4 + group)
                shared_sb = gl.load(WS + (256 * 48 + tile * BN // 128) * 4 + group)
                operands += ((a, b, sa, sb, shared_a, shared_b, shared_sa, shared_sb),)
            else:
                operands += ((a, b, sa, sb),)
        for stage in gl.static_range(P.prefetch):
            if SEPARATE_SHARED:
                a, b, sa, sb, shared_a, shared_b, shared_sa, shared_sb = operands[stage]
            else:
                a, b, sa, sb = operands[stage]
            partial = gl.amd.cdna4.mfma_scaled(a, None, 'e4m3', b, None, 'e4m3', gl.full((R, BN * R), 0, gl.float32, ml))
            diagonal = gl.sum(gl.gather(partial, (cn // BN)[None, :], 0), 0)
            acc += diagonal * sa * sb
            if SEPARATE_SHARED:
                shared_partial = gl.amd.cdna4.mfma_scaled(shared_a, None, 'e4m3', shared_b, None, 'e4m3', gl.full((1, BN), 0, gl.float32, ml))
                shared_acc += shared_partial * shared_sa * shared_sb
    weights = gl.load(Weights + row * 9 + cn // BN, mask_c, zero)
    contribution = gl.reshape(acc.to(gl.bfloat16).to(gl.float32) * weights, (R, BN))
    finish: gl.constexpr = gl.BlockedLayout([1, 1], [1, 64], [1, NW], [1, 0])
    contribution = gl.convert_layout(contribution, finish)
    sr = gl.arange(0, R, layout=gl.SliceLayout(1, finish))
    output_n = tile * BN + gl.arange(0, BN, layout=gl.SliceLayout(0, finish))
    result = gl.full((BN,), 0, gl.float32, gl.SliceLayout(0, finish))
    for slot in gl.static_range(LIVE):
        result += gl.sum(gl.where(sr[:, None] == slot, contribution, 0), 0)
    if SEPARATE_SHARED:
        shared_value = gl.sum(shared_acc.to(gl.bfloat16).to(gl.float32), 0)
        result += gl.convert_layout(shared_value, result.type.layout)
    gl.store(Out + row * 6144 + output_n, result)

class _Projection(NamedTuple):
    cols: int
    rows: int
    k_width: int
    splits: int = 1
    prefetch: int = 1
    native: bool = False
    buffer_input: bool = False
    buffer_output: bool = False
    cache: str = ''

class _PackedDown(NamedTuple):
    cols: int
    k_width: int = 32
    prefetch: int = 1

class _Schedule(NamedTuple):
    up: _Projection
    down: _Projection | _PackedDown
    router_rows: int
    up_axes: tuple[int, int, int] = (0, 1, 2)
    down_waves: int = 0
_SCHEDULES = {1: _Schedule(_Projection(16, 1, 32, splits=4, prefetch=12, native=True, buffer_input=True, buffer_output=True, cache='.cg'), _PackedDown(8, prefetch=4), router_rows=1, down_waves=2), 2: _Schedule(_Projection(32, 2, 16, splits=4, prefetch=6, native=True, buffer_input=True, buffer_output=True), _PackedDown(8, prefetch=4), router_rows=1), 4: _Schedule(_Projection(32, 16, 32, splits=6, prefetch=8, native=True, buffer_output=True), _PackedDown(16, k_width=16), router_rows=2, down_waves=2), 8: _Schedule(_Projection(16, 8, 16, splits=12, prefetch=4, buffer_output=True), _Projection(32, 8, 16, buffer_input=True, buffer_output=True, cache='.cg'), router_rows=4, up_axes=(2, 1, 0)), 16: _Schedule(_Projection(16, 16, 16, splits=4, prefetch=12, native=True, buffer_input=True, buffer_output=True), _Projection(32, 16, 16, buffer_input=True, buffer_output=True, cache='.cg'), router_rows=4, up_axes=(2, 1, 0))}

def sigmoid_router_quantized_moe(hidden: torch.Tensor, router: torch.Tensor, correction_bias: torch.Tensor, w13: torch.Tensor, w13_scales: torch.Tensor, w2: torch.Tensor, w2_scales: torch.Tensor, *, precision: str='fp8', topk: int=8, mx_scale_mode: str='ceil', intermediate_dim: int | None=None, expert_offset: int=0, shared_expert: bool=False, routed_scaling_factor: float=1.0, out: torch.Tensor) -> torch.Tensor:
    m, h = hidden.shape
    f = w13.shape[1] // 2 if intermediate_dim is None else intermediate_dim
    assert m in _SCHEDULES and precision == 'fp8' and (h == 6144) and (f == 512)
    assert router.shape == (256, h) and w13.shape == (257, 1024, h)
    assert w2.shape == (257, h, f) and topk == 8 and shared_expert and (expert_offset == 0)
    assert hidden.dtype == torch.bfloat16 and router.dtype == torch.bfloat16
    schedule = _SCHEDULES[m]
    up = schedule.up
    single_up = up._replace(rows=1) if m == 16 else None
    routes = m * 9
    fused_router = m <= 4
    bm = up.rows
    logits = None if fused_router else torch.empty((m, 12, 256) if m == 16 else (m, 256), device=hidden.device, dtype=torch.float64 if m == 16 else router.dtype)
    ids = torch.empty((routes,), device=hidden.device, dtype=torch.int32)
    weights = torch.empty((routes,), device=hidden.device, dtype=torch.float32)
    hq = torch.empty((m, h), device=hidden.device, dtype=torch.float8_e4m3fn)
    hs = torch.empty((m, 48), device=hidden.device, dtype=torch.float32)
    projected = torch.empty((routes, up.splits, 1024), device=hidden.device, dtype=torch.float32)
    aq = torch.empty((routes, f), device=hidden.device, dtype=torch.float8_e4m3fn)
    asc = torch.empty((routes, 4), device=hidden.device, dtype=torch.float32)
    scores = torch.empty((m, 256), device=hidden.device, dtype=torch.uint32 if m == 4 else torch.float32) if fused_router else None
    probs = torch.empty((m, 256), device=hidden.device, dtype=torch.float32) if fused_router else None
    down = None if fused_router else torch.empty((routes, h), device=hidden.device, dtype=torch.bfloat16)
    route_map = torch.empty((routes, bm + 1), device=hidden.device, dtype=torch.int32) if m >= 8 else None
    jobs = m * 8 + 1
    up_tiles = 1024 // up.cols
    up_grid = [0, 0, 0]
    for axis, extent in zip(schedule.up_axes, (up_tiles, jobs, up.splits)):
        up_grid[axis] = extent
    router_rows = schedule.router_rows
    if m == 16:
        _prepare_matrix[16, 12](hidden, router, hq, hs, logits, m, 12, 16, 8, num_warps=1)
    else:
        _prepare[m // router_rows, 304 if fused_router else 256](hidden, router, hq, hs, correction_bias, scores if fused_router else logits, probs, ROWS=router_rows, ORDERS=m == 4, num_warps=4)
    if not fused_router:
        _select[m,](logits, correction_bias, ids, weights, routed_scaling_factor, 12 if m == 16 else 0, num_warps=1)
    _project_up[up_grid](hq, hs, w13, w13_scales, ids, projected, scores, probs, weights, route_map, m, routed_scaling_factor, up, schedule.up_axes, single_up, num_warps=1)
    _activate_quant[routes, 4](projected, aq, asc, up.splits, num_warps=1)
    policy = schedule.down
    if fused_router:
        _down_packed[h // policy.cols, m](aq, asc, w2, w2_scales, ids, weights, out, policy, SEPARATE_SHARED=m <= 2, num_warps=1, waves_per_eu=schedule.down_waves)
    else:
        assert policy.rows == bm
        _project_down[h // policy.cols, jobs](aq, asc, w2, w2_scales, down, route_map, m, policy, num_warps=1)
        _combine[m, h // 256](down, weights, out, num_warps=1)
    return out


def run(
    *,
    hidden_states,
    router_weight,
    correction_bias,
    w1,
    w1_scale,
    w2,
    w2_scale,
    topk,
    num_expert_group,
    topk_group,
    renormalize,
    scoring_func,
    routed_scaling_factor,
    out_dtype,
    out,
):
    # The Point fixes the routing (the top 8 of 256 experts in one group, renormalized
    # sigmoid scores times routed_scaling_factor), the shared expert in the last slot and
    # out's dtype; w2's last dimension is this rank's share of the intermediate size.
    sigmoid_router_quantized_moe(
        hidden_states,
        router_weight,
        correction_bias,
        w1,
        w1_scale,
        w2,
        w2_scale,
        precision="fp8",
        topk=topk,
        intermediate_dim=w2.shape[2],
        shared_expert=True,
        routed_scaling_factor=routed_scaling_factor,
        out=out,
    )
